#include <stdio.h>
int main(void) {
    int n = 2;
    int values[2] = {2, 3};
    int target = 2;
    int answer = -1;
    for (int i = 0; i < n; i = i + 1) {
        if (values[i] == target) {
            answer = i;
            break;
        }
    }
    printf("%d\n", answer);
    return 0;
}
